{"function": "() => {
    // Extract all text content from the article page
    const articleText = document.querySelector('article')?.innerText || document.body.innerText;

    // Extract all links with their text and URLs
    const allLinks = Array.from(document.querySelectorAll('a')).map(link => ({
        text: link.textContent.trim(),
        href: link.href,
        isExternal: !link.href.includes('universetoday.com')
    }));

    // Filter for external links (likely scientific papers and resources)
    const externalLinks = allLinks.filter(link => link.isExternal && link.text && link.text.length > 0);

    // Filter for links in the "For More Information" section
    const forMoreInfoLinks = [];
    const headings = Array.from(document.querySelectorAll('h2'));
    const forMoreInfoHeading = headings.find(h => h.textContent.includes('For More Information'));
    if (forMoreInfoHeading) {
        let nextElement = forMoreInfoHeading.nextElementSibling;
        while (nextElement && !nextElement.matches('h2')) {
            const linksInSection = Array.from(nextElement.querySelectorAll('a')).map(link => ({
                text: link.textContent.trim(),
                href: link.href
            }));
            forMoreInfoLinks.push(...linksInSection);
            nextElement = nextElement.nextElementSibling;
        }
    }

    return {
        articleTitle: document.title,
        articleFullText: articleText,
        allLinksCount: allLinks.length,
        externalLinksCount: externalLinks.length,
        externalLinks: externalLinks,
        forMoreInfoLinks: forMoreInfoLinks,
        articleDate: document.querySelector('time')?.textContent || 'June 06, 2023',
        author: document.querySelector('a[href*="cc-petersen"]')?.textContent || 'Carolyn Collins Petersen'
    };
}"}

